def priority(item: float, bins: np.ndarray) -> np.ndarray:
    diff = bins - item
    return np.where(diff >= 0, -diff, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    diff = bins - item
    return np.where(diff >= 0, np.where(diff <= item, diff, -(diff - item)), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    diff = bins - item
    return np.where(diff >= 0, np.floor_divide(bins, item), -np.inf)
